INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Pseudocode ein wichtiger Bestandteil der Softwareentwicklung?', 2, '[{"text": "Ja", "correct": true, "because": "Hilft bei der Planung"}, {"text": "Nein", "correct": false, "because": "Es ist nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt Pseudocode?', 3, '[{"text": "Algorithmus verständlich darstellen", "correct": true, "because": "Fördert Planung"}, {"text": "Programm direkt ausführen", "correct": false, "because": "Nicht kompilierbar"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Pseudocode ist sprachunabhängig. b) Er ist eine Programmiersprache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, kein Code"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise zu Pseudocode?', 4, '[{"text": "Schleifen", "correct": true, "because": "Wiederholungen"}, {"text": "Unklare Begriffe", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Bedingungen", "correct": true, "because": "Entscheidungen"}, {"text": "Variablen", "correct": true, "because": "Datenverarbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Pseudocode direkt ausgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nicht maschinenlesbar"}, {"text": "Ja", "correct": false, "because": "Nur Planungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Pseudocode in der Softwareentwicklung?', 3, '[{"text": "Planung und Strukturierung von Programmen", "correct": true, "because": "Fördert Übersicht"}, {"text": "Fehler direkt beheben", "correct": false, "because": "Debugging später"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Pseudocode nur für Anfänger relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Profis nutzen es"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat eine Schleife im Pseudocode?', 3, '[{"text": "Wiederholung von Anweisungen", "correct": true, "because": "Logik darstellen"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Funktion"}, {"text": "Hardware steuern", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Pseudocode ist leicht lesbar. b) Er muss kompilierbar sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nicht ausführbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Pseudocode?', 3, '[{"text": "Planung wird schwieriger", "correct": true, "because": "Struktur fehlt"}, {"text": "Programmierung schneller", "correct": false, "because": "Eher Fehler"}, {"text": "Code direkt ausführbar", "correct": false, "because": "Unsinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Pseudocode ohne Bedingungen erstellt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Einfache Abläufe möglich"}, {"text": "Nein", "correct": false, "because": "Flexibilität gegeben"}]');